class WeaponKit private constructor(private val builders: Map<String, () -> Weapon>) {
    fun create(key: String): Weapon =
        builders[key]?.invoke() ?: error("unknown weapon: $key (have ${builders.keys})")

    companion object {
        fun of(configure: MutableMap<String, () -> Weapon>.() -> Unit): WeaponKit =
            WeaponKit(mutableMapOf<String, () -> Weapon>().apply(configure).toMap())
    }
}
